from controls import *@templatename("Addressee/popup:Stack")class Stack(CatalogTemplateList):    """Панель выбора заказчика плана"""    search_field = ControlsSearchInput(SabyBy.DATA_QA, "addressee-selector-root", 'Поиск заказчика')    customer_tbl = ControlsTreeGridView(SabyBy.DATA_QA, "staffCommon-List_view", 'Таблица заказчиков')    def customer_choice(self, executor):        """Поиск сотрудника"""        self.search_field.type_in(executor)        self.customer_tbl.item(contains_text=executor).click()